INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ADD_SUB_RULES.M_MINUS_NEGATIVE_STAYS_MINUS', 'MATH.G9.NUMBER.INTEGERS.INT_ADD_SUB_RULES', 'Treats subtracting a negative number as subtracting its size.', '{"question":"5 - (-3)","wrong_answer":"2","correct_answer":"8"}'::jsonb, 'Sees two minus signs and keeps only one subtraction.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Taking away a debt makes you richer: 5 - (-3) = 5 + 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ADD_SUB_RULES.M_ADD_NEGATIVE_AS_ADD', 'MATH.G9.NUMBER.INTEGERS.INT_ADD_SUB_RULES', 'Adds the size of a negative number as if it were positive.', '{"question":"4 + (-9)","wrong_answer":"13","correct_answer":"-5"}'::jsonb, 'Ignores the sign inside the bracket.', 'The answer 13 as a wrong option, with a reason that names the idea.', 'Adding -9 moves 9 steps left: 4 + (-9) = 4 - 9 = -5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ADD_SUB_RULES.M_SIGN_OF_LARGER_IGNORED', 'MATH.G9.NUMBER.INTEGERS.INT_ADD_SUB_RULES', 'Gets the size right but gives the sign of the first number, not of the larger one.', '{"question":"-3 + 10","wrong_answer":"-7","correct_answer":"7"}'::jsonb, 'Copies the first sign into the answer.', 'The answer -7 as a wrong option, with a reason that names the idea.', 'The answer takes the sign of the number further from zero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ADD_SUB_RULES.M_TWO_NEGATIVES_POSITIVE_SUM', 'MATH.G9.NUMBER.INTEGERS.INT_ADD_SUB_RULES', 'Uses the multiplication rule for adding: two negatives make a positive.', '{"question":"-6 + (-4)","wrong_answer":"10","correct_answer":"-10"}'::jsonb, 'Mixes up "two negatives make a positive" (for products) with sums.', 'The answer 10 as a wrong option, with a reason that names the idea.', 'Two debts added together are a bigger debt: -6 + (-4) = -10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ADD_SUB_RULES.M_ADD_POSITIVE_MOVES_DOWN', 'MATH.G9.NUMBER.INTEGERS.INT_ADD_SUB_RULES', 'Moves down the number line when adding a positive number to a negative one.', '{"question":"-5 + 3","wrong_answer":"-8","correct_answer":"-2"}'::jsonb, 'Thinks a negative start means every move is downward.', 'The answer -8 as a wrong option, with a reason that names the idea.', 'Adding a positive number always moves up (right), whatever the start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES.M_NEG_TIMES_POS_POSITIVE', 'MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES', 'Gives a positive answer when a negative and a positive number are multiplied.', '{"question":"(-4) x 6","wrong_answer":"24","correct_answer":"-24"}'::jsonb, 'Drops the sign or thinks only like signs matter.', 'The answer 24 as a wrong option, with a reason that names the idea.', 'Four falls of 6 m each is a fall of 24 m: different signs give a negative.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES.M_NEG_TIMES_NEG_NEGATIVE', 'MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES', 'Gives a negative answer when two negative numbers are multiplied.', '{"question":"(-4) x (-6)","wrong_answer":"-24","correct_answer":"24"}'::jsonb, 'Thinks a negative in the question means a negative answer.', 'The answer -24 as a wrong option, with a reason that names the idea.', 'Continue the pattern 2 x -6 = -12, 1 x -6 = -6, 0 x -6 = 0, -1 x -6 = 6: same signs give a positive.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES.M_PRODUCT_SIGN_WRONG', 'MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES', 'Gets the size of a product right but the sign the wrong way round.', '{"question":"(-3) x (-5)","wrong_answer":"-15","correct_answer":"15"}'::jsonb, 'Guesses the sign after multiplying the sizes.', 'The answer -15 as a wrong option, with a reason that names the idea.', 'Decide the sign first: same signs positive, different signs negative.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES.M_QUOTIENT_SIGN_WRONG', 'MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES', 'Gives a positive answer when a positive number is divided by a negative one.', '{"question":"18 / (-3)","wrong_answer":"6","correct_answer":"-6"}'::jsonb, 'Thinks the sign rules are only for multiplying.', 'The answer 6 as a wrong option, with a reason that names the idea.', 'Division follows the same sign rules: -6 x -3 = 18, so 18 / (-3) = -6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES.M_TIMES_AS_SUBTRACT', 'MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES', 'Subtracts when the sign between the numbers is a multiplication.', '{"question":"(-3) x (-4)","wrong_answer":"1","correct_answer":"12"}'::jsonb, 'Reads the minus signs and forgets the operation.', 'The answer 1 as a wrong option, with a reason that names the idea.', 'Read the operation sign between the brackets first: x means multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES.M_DIVIDE_AS_MULTIPLY', 'MATH.G9.NUMBER.INTEGERS.INT_MUL_DIV_RULES', 'Multiplies when the question is a division.', '{"question":"24 / (-4)","wrong_answer":"-96","correct_answer":"-6"}'::jsonb, 'Remembers the sign rule and loses the operation.', 'The answer -96 as a wrong option, with a reason that names the idea.', 'Check the sign between the numbers: / means share or divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ORDER_OF_OPERATIONS.M_LEFT_TO_RIGHT_ALWAYS', 'MATH.G9.NUMBER.INTEGERS.INT_ORDER_OF_OPERATIONS', 'Works every expression from left to right, adding before multiplying.', '{"question":"7 - 3 x (-4)","wrong_answer":"-16","correct_answer":"19"}'::jsonb, 'Reads like a sentence and ignores the order of operations.', 'The answer -16 as a wrong option, with a reason that names the idea.', 'Multiplication and division come before addition and subtraction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ORDER_OF_OPERATIONS.M_NEGATIVE_CHANGES_ORDER', 'MATH.G9.NUMBER.INTEGERS.INT_ORDER_OF_OPERATIONS', 'Believes a negative number changes which operation is done first.', '{"question":"-12 / 4 + 5","wrong_answer":"-12 / 9","correct_answer":"2"}'::jsonb, 'Thinks the minus sign is an operation to be done last.', 'The answer -12 / 9 as a wrong option, with a reason that names the idea.', 'A negative sign belongs to its number; the order of operations stays the same.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ORDER_OF_OPERATIONS.M_SIGN_LOST_IN_PRODUCT', 'MATH.G9.NUMBER.INTEGERS.INT_ORDER_OF_OPERATIONS', 'Works out the product first but drops its sign before the next step.', '{"question":"10 + 2 x (-3)","wrong_answer":"16","correct_answer":"4"}'::jsonb, 'Writes only the size of each product.', 'The answer 16 as a wrong option, with a reason that names the idea.', 'Write each product with its sign before going on: 2 x (-3) = -6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ORDER_OF_OPERATIONS.M_MINUS_TIMES_NEG_DOUBLED', 'MATH.G9.NUMBER.INTEGERS.INT_ORDER_OF_OPERATIONS', 'Changes minus a negative product into plus and then changes the sign again.', '{"question":"8 - 2 x (-5)","wrong_answer":"-2","correct_answer":"18"}'::jsonb, 'Applies the sign rule twice to the same sign.', 'The answer -2 as a wrong option, with a reason that names the idea.', 'Find 2 x (-5) = -10 first, then 8 - (-10) = 18: one change, once.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_BRACKETS_COMBINED.M_BRACKET_NOT_FIRST', 'MATH.G9.NUMBER.INTEGERS.INT_BRACKETS_COMBINED', 'Multiplies into the bracket before working it out, using only one number in it.', '{"question":"(-5 + 2) x (-4)","wrong_answer":"22","correct_answer":"12"}'::jsonb, 'Multiplies the last number in the bracket only.', 'The answer 22 as a wrong option, with a reason that names the idea.', 'Work out the whole bracket first: -5 + 2 = -3, then -3 x -4 = 12.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_BRACKETS_COMBINED.M_SIGN_OF_SUM_LOST', 'MATH.G9.NUMBER.INTEGERS.INT_BRACKETS_COMBINED', 'Writes the size of the bracket and drops its negative sign.', '{"question":"(-9 + 4) x 2","wrong_answer":"10","correct_answer":"-10"}'::jsonb, 'Subtracts the smaller from the larger and forgets which was negative.', 'The answer 10 as a wrong option, with a reason that names the idea.', 'The bracket takes the sign of the number further from zero: -9 + 4 = -5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_BRACKETS_COMBINED.M_SIGNS_SWAPPED_AT_END', 'MATH.G9.NUMBER.INTEGERS.INT_BRACKETS_COMBINED', 'Gets each part right but changes the sign of a part when putting them together.', '{"question":"12 - (-6)","wrong_answer":"-18","correct_answer":"18"}'::jsonb, 'Copies the parts across and flips a sign by mistake.', 'The answer -18 as a wrong option, with a reason that names the idea.', 'Copy each part with its own sign, then change only minus a negative into plus.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_BRACKETS_COMBINED.M_DIVIDE_BEFORE_BRACKET', 'MATH.G9.NUMBER.INTEGERS.INT_BRACKETS_COMBINED', 'Divides only the first number in the bracket instead of the whole bracket.', '{"question":"(-8 + 2) / 2","wrong_answer":"-2","correct_answer":"-3"}'::jsonb, 'Does the division as soon as it sees a number next to it, before the bracket is finished.', 'The answer -2 as a wrong option, with a reason that names the idea.', 'Finish the bracket to one number (-6), then divide it: -6 / 2 = -3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT.M_OVERDRAFT_AS_POSITIVE', 'MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT', 'Treats an overdrawn balance as money in the account.', '{"question":"Balance -2,000 shillings; pay in 5,000. Balance now?","wrong_answer":"7,000","correct_answer":"3,000"}'::jsonb, 'Reads the amount and ignores what "overdrawn" means.', 'The answer 7,000 as a wrong option, with a reason that names the idea.', 'Overdrawn means the shop owes the bank: start below zero.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT.M_PAYOUT_ADDED', 'MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT', 'Adds money paid out instead of taking it away.', '{"question":"Balance 3,000; pay out 4,500. Balance now?","wrong_answer":"7,500","correct_answer":"-1,500"}'::jsonb, 'Adds every amount in the story.', 'The answer 7,500 as a wrong option, with a reason that names the idea.', 'Money out lowers the balance: subtract it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT.M_OPENING_BALANCE_LEFT_OUT', 'MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT', 'Works only with the changes and forgets the starting balance or floor.', '{"question":"Balance -1,500; pay in 6,000; pay out 2,000. Balance?","wrong_answer":"4,000","correct_answer":"2,500"}'::jsonb, 'Thinks the story starts at zero.', 'The answer 4,000 as a wrong option, with a reason that names the idea.', 'Write the opening balance first, then each change.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT.M_START_SIGN_DROPPED', 'MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT', 'Starts a lift or a balance at the positive number when the story starts below zero.', '{"question":"A lift at floor -3 goes up 5 floors. Floor?","wrong_answer":"8","correct_answer":"2"}'::jsonb, 'Reads the number without its minus sign.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Floor -3 is three floors below the ground floor: start there.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT.M_DOWN_AS_UP', 'MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT', 'Adds a downward move instead of subtracting it.', '{"question":"A lift at floor 2 goes down 6 floors. Floor?","wrong_answer":"8","correct_answer":"-4"}'::jsonb, 'Adds every number in the story.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Down means take away: 2 - 6 = -4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT.M_SIGN_FLIPPED_AT_END', 'MATH.G9.NUMBER.INTEGERS.INT_BALANCE_CONTEXT', 'Gets the right size but changes the sign of the final answer.', '{"question":"Floor -3, up 4, down 6. Floor?","wrong_answer":"5","correct_answer":"-5"}'::jsonb, 'Changes the sign at the end to "tidy" the answer.', 'The answer 5 as a wrong option, with a reason that names the idea.', 'Track each move from the start; the sign you land on is the answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ALTITUDE_DIFFERENCE.M_DEPTH_SUBTRACTED', 'MATH.G9.NUMBER.INTEGERS.INT_ALTITUDE_DIFFERENCE', 'Subtracts the depth below sea level from the height above it instead of adding.', '{"question":"Hill 450 m, mine floor -120 m. How much higher is the hill?","wrong_answer":"330 m","correct_answer":"570 m"}'::jsonb, 'Sees two numbers and takes the smaller away.', 'The answer 330 m as a wrong option, with a reason that names the idea.', 'The gap goes down to zero and on below it: 450 - (-120) = 450 + 120.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ALTITUDE_DIFFERENCE.M_ONE_SIDE_ONLY', 'MATH.G9.NUMBER.INTEGERS.INT_ALTITUDE_DIFFERENCE', 'Counts only the part of the gap on one side of sea level.', '{"question":"Hill 450 m, borehole bottom -80 m. Gap?","wrong_answer":"80 m","correct_answer":"530 m"}'::jsonb, 'Starts or stops counting at zero.', 'The answer 80 m as a wrong option, with a reason that names the idea.', 'Count from the lowest up to zero, then from zero to the highest, and add.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ALTITUDE_DIFFERENCE.M_HIGHEST_ALONE', 'MATH.G9.NUMBER.INTEGERS.INT_ALTITUDE_DIFFERENCE', 'Gives the altitude of the highest place as the gap.', '{"question":"Highest 300 m, lowest -50 m. How much higher?","wrong_answer":"300 m","correct_answer":"350 m"}'::jsonb, 'Answers "how high" instead of "how much higher than".', 'The answer 300 m as a wrong option, with a reason that names the idea.', 'A gap needs two places: highest minus lowest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.INTEGERS.INT_ALTITUDE_DIFFERENCE.M_WRONG_PAIR_CHOSEN', 'MATH.G9.NUMBER.INTEGERS.INT_ALTITUDE_DIFFERENCE', 'Uses the first and last rows of the table instead of the highest and lowest values.', '{"question":"Altitudes 200, -30, 520, -10. Highest minus lowest?","wrong_answer":"210","correct_answer":"550"}'::jsonb, 'Takes rows by position, not by value.', 'The answer 210 as a wrong option, with a reason that names the idea.', 'Sort the values first; pick the largest and the smallest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION.M_CUBE_AS_TRIPLE', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION', 'Multiplies the number by 3 instead of by itself three times.', '{"question":"What is 4 cubed?","wrong_answer":"12","correct_answer":"64"}'::jsonb, 'Reads the small 3 as "times 3".', 'The answer 12 as a wrong option, with a reason that names the idea.', 'The small 3 counts factors: 4 x 4 x 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION.M_SQUARE_AS_DOUBLE', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION', 'Doubles the number when squaring it on the way to the cube.', '{"question":"1.3 x 1.3","wrong_answer":"2.6","correct_answer":"1.69"}'::jsonb, 'Adds the number to itself.', 'The answer 2.6 as a wrong option, with a reason that names the idea.', 'Squaring is multiplying by itself, not adding.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION.M_NEGATIVE_CUBE_POSITIVE', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION', 'Gives a positive cube for a negative number.', '{"question":"(-3) cubed","wrong_answer":"27","correct_answer":"-27"}'::jsonb, 'Remembers that two negatives make a positive and stops there.', 'The answer 27 as a wrong option, with a reason that names the idea.', 'Two negatives give a positive, and the third makes it negative again: (-3)(-3)(-3) = -27.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION.M_TIMES_TWO_NOT_N', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION', 'Multiplies the square by 2 instead of by the number again.', '{"question":"1.2 squared is 1.44. Now find 1.2 cubed.","wrong_answer":"2.88","correct_answer":"1.728"}'::jsonb, 'Thinks the third step doubles.', 'The answer 2.88 as a wrong option, with a reason that names the idea.', 'Each step multiplies by the same number: 1.44 x 1.2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION.M_SQUARE_AS_CUBE', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION', 'Takes a square number for a cube number.', '{"question":"Which is a cube number: 81, 100, 125?","wrong_answer":"81","correct_answer":"125"}'::jsonb, 'Knows square numbers better and mixes the two.', 'The answer 81 as a wrong option, with a reason that names the idea.', 'A cube is three equal factors: 5 x 5 x 5 = 125. 81 = 9 x 9 has no three equal factors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION.M_MULTIPLE_OF_THREE_AS_CUBE', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION', 'Thinks a multiple of 3 is a cube number.', '{"question":"Is 45 a cube number?","wrong_answer":"Yes, it is in the 3 times table","correct_answer":"No"}'::jsonb, 'Links the cube sign 3 with the 3 times table.', 'The answer Yes, it is in the 3 times table as a wrong option, with a reason that names the idea.', 'A cube is a number times itself three times; test 3 x 3 x 3 = 27 and 4 x 4 x 4 = 64.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION.M_NEAR_CUBE_ACCEPTED', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_BY_MULTIPLICATION', 'Accepts a number one more or one less than a cube as a cube.', '{"question":"Is 126 a cube number?","wrong_answer":"Yes","correct_answer":"No (125 is)"}'::jsonb, 'Checks roughly, not exactly.', 'The answer Yes as a wrong option, with a reason that names the idea.', 'Multiply the nearest root three times and compare exactly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_FROM_TABLE.M_NEIGHBOUR_COLUMN_READ', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_FROM_TABLE', 'Reads the column next to the right one.', '{"question":"Table cube of 2.37: row 2.3, column 7.","wrong_answer":"the value in column 6","correct_answer":"the value in column 7"}'::jsonb, 'Loses place in a crowded table.', 'The answer the value in column 6 as a wrong option, with a reason that names the idea.', 'Put a ruler under the row and a finger on the column heading.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_FROM_TABLE.M_ROW_ABOVE_READ', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_FROM_TABLE', 'Reads the row above or below the right one.', '{"question":"Table cube of 2.37: which row?","wrong_answer":"2.2","correct_answer":"2.3"}'::jsonb, 'Moves to the wrong row while finding the column.', 'The answer 2.2 as a wrong option, with a reason that names the idea.', 'The row is the first two digits; read along that row only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_FROM_TABLE.M_TABLE_SCALED_ONCE', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_FROM_TABLE', 'Moves the decimal point once for a factor of 10 instead of three times.', '{"question":"2.37 cubed is 13.31. Find 23.7 cubed.","wrong_answer":"133.1","correct_answer":"13,310"}'::jsonb, 'Treats the cube like the number itself.', 'The answer 133.1 as a wrong option, with a reason that names the idea.', 'Ten times the number is 10 x 10 x 10 times the cube.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_FROM_TABLE.M_TABLE_NOT_ADJUSTED', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_FROM_TABLE', 'Gives the table value for a number outside 1 to 10 without adjusting.', '{"question":"Find 23.7 cubed from the table.","wrong_answer":"13.31","correct_answer":"13,310"}'::jsonb, 'Reads the table and stops.', 'The answer 13.31 as a wrong option, with a reason that names the idea.', 'The table is for 2.37; 23.7 is ten times that, so multiply by 1,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_FROM_TABLE.M_CUBE_AS_TRIPLE_TABLE', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_FROM_TABLE', 'Multiplies the number by 3 instead of reading the table.', '{"question":"Find 2.37 cubed.","wrong_answer":"7.11","correct_answer":"13.31"}'::jsonb, 'Reads the small 3 as times 3.', 'The answer 7.11 as a wrong option, with a reason that names the idea.', 'A cube is three equal factors; use the table of cubes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_ROOT_BY_FACTORS.M_WHOLE_GROUP_TAKEN', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_ROOT_BY_FACTORS', 'Takes a whole group of three primes instead of one prime from it.', '{"question":"1,000 = (2x2x2)(5x5x5). Cube root?","wrong_answer":"1,000","correct_answer":"10"}'::jsonb, 'Thinks the group itself is the part of the root.', 'The answer 1,000 as a wrong option, with a reason that names the idea.', 'One prime from each group of three: 2 x 5 = 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_ROOT_BY_FACTORS.M_ROOT_PRIMES_ADDED', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_ROOT_BY_FACTORS', 'Adds the primes taken from each group instead of multiplying them.', '{"question":"216 = (2x2x2)(3x3x3). Cube root?","wrong_answer":"5","correct_answer":"6"}'::jsonb, 'Combines the numbers by adding.', 'The answer 5 as a wrong option, with a reason that names the idea.', 'The root is a product: 2 x 3 = 6. Check: 6 x 6 x 6 = 216.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_ROOT_BY_FACTORS.M_FACTOR_COUNT_OF_ROOT', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_ROOT_BY_FACTORS', 'Counts the primes of the root instead of the cube.', '{"question":"How many 2s are in the prime factors of 1,728 = 12 cubed?","wrong_answer":"2","correct_answer":"6"}'::jsonb, 'Writes the factors of 12 and forgets the cube has three times as many.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'Each prime of the root appears three times in the cube.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_ROOT_BY_FACTORS.M_ROOT_AS_DIVIDE_BY_THREE', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_ROOT_BY_FACTORS', 'Divides the number by 3 to find its cube root.', '{"question":"Cube root of 27,000?","wrong_answer":"9,000","correct_answer":"30"}'::jsonb, 'Links "cube root" with "divide by 3".', 'The answer 9,000 as a wrong option, with a reason that names the idea.', 'The root is the number that, multiplied three times, gives 27,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_ROOT_BY_FACTORS.M_PRIMES_USED_ONCE', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.CUBE_ROOT_BY_FACTORS', 'Multiplies each different prime once, whatever the number of groups.', '{"question":"5,832 = 2x2x2x3x3x3x3x3x3. Cube root?","wrong_answer":"6","correct_answer":"18"}'::jsonb, 'Takes each prime once instead of once per group.', 'The answer 6 as a wrong option, with a reason that names the idea.', 'Three 3s make one group; six 3s make two groups: 2 x 3 x 3 = 18.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.PERFECT_CUBE_MULTIPLIER.M_EACH_PRIME_ONCE', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.PERFECT_CUBE_MULTIPLIER', 'Multiplies by each prime factor once.', '{"question":"Smallest number to multiply 72 = 2x2x2x3x3 by to make a cube?","wrong_answer":"6","correct_answer":"3"}'::jsonb, 'Thinks every prime needs one more.', 'The answer 6 as a wrong option, with a reason that names the idea.', 'Count what each prime is short of three: 2 is complete, 3 needs one more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.PERFECT_CUBE_MULTIPLIER.M_MULTIPLY_BY_ITSELF', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.PERFECT_CUBE_MULTIPLIER', 'Multiplies the number by itself.', '{"question":"Smallest multiplier for 72?","wrong_answer":"72","correct_answer":"3"}'::jsonb, 'Thinks squaring the number makes it a cube.', 'The answer 72 as a wrong option, with a reason that names the idea.', 'Multiplying by itself doubles every count; count the primes instead.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.PERFECT_CUBE_MULTIPLIER.M_SQUARE_RULE_USED', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.PERFECT_CUBE_MULTIPLIER', 'Completes pairs (as for a square) instead of groups of three.', '{"question":"Smallest multiplier for 72 to make a cube?","wrong_answer":"2","correct_answer":"3"}'::jsonb, 'Uses the rule for perfect squares.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'A cube needs groups of three, not pairs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.PERFECT_CUBE_MULTIPLIER.M_MISSING_COUNT_WRONG', 'MATH.G9.NUMBER.CUBES_AND_CUBE_ROOTS.PERFECT_CUBE_MULTIPLIER', 'Adds one of each short prime even when two are missing.', '{"question":"Smallest multiplier for 50 = 2x5x5?","wrong_answer":"10","correct_answer":"20"}'::jsonb, 'Adds one of each without counting how many are missing.', 'The answer 10 as a wrong option, with a reason that names the idea.', '2 needs two more (2 x 2) and 5 needs one more: 4 x 5 = 20.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
